#!/usr/bin/env node
/** 清理 OV session_commit 队列（pending + running），为批量 import 让路 */
const API = "http://127.0.0.1:1933";

async function listTasks() {
  const j = await fetch(`${API}/api/v1/tasks?limit=200`).then((r) => r.json());
  return j.result || [];
}

async function cancel(id) {
  const r = await fetch(`${API}/api/v1/tasks/${id}/cancel`, { method: "POST" });
  const j = await r.json().catch(() => ({}));
  return { ok: r.ok, j };
}

let rounds = 0;
let cancelled = 0;
while (rounds < 15) {
  rounds++;
  const tasks = await listTasks();
  const targets = tasks.filter(
    (t) =>
      t.task_type === "session_commit" &&
      (t.status === "pending" || t.status === "running")
  );
  if (!targets.length) break;
  for (const t of targets) {
    const { ok } = await cancel(t.task_id);
    if (ok) cancelled++;
    await new Promise((r) => setTimeout(r, 50));
  }
  console.log(`round ${rounds}: cancelled batch ${targets.length}, total ${cancelled}`);
  await new Promise((r) => setTimeout(r, 500));
}

const left = (await listTasks()).filter(
  (t) => t.task_type === "session_commit" && ["pending", "running"].includes(t.status)
);
console.log(JSON.stringify({ cancelled, remaining_commit: left.length, rounds }, null, 2));
if (left.length) {
  for (const t of left.slice(0, 10)) console.log("left", t.status, t.task_id.slice(0, 8), t.resource_id?.slice(0, 36));
  process.exitCode = 1;
}

#!/usr/bin/env node
/** import 前门禁：1933 health + 3425 VLM 探针 + commit 队列深度 */
const OV = "http://127.0.0.1:1933";
const VLM = "http://127.0.0.1:3425/v1/chat/completions";
const MAX_QUEUE = Number(process.env.OV_MAX_COMMIT_QUEUE || 8);

async function fail(msg) {
  console.error("[preflight] " + msg);
  process.exit(1);
}

try {
  const h = await fetch(`${OV}/health`, { signal: AbortSignal.timeout(8000) }).then((r) => r.json());
  if (h.status !== "ok" && h.healthy !== true) await fail("OV health 异常: " + JSON.stringify(h));
} catch (e) {
  await fail("OV 1933 不可达: " + e.message);
}

try {
  const body = {
    model: "auto/hy3",
    messages: [{ role: "user", content: "reply ok only" }],
    max_tokens: 8,
  };
  const j = await fetch(VLM, {
    method: "POST",
    headers: { Authorization: "Bearer magpie", "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(45000),
  }).then((r) => r.json());
  const txt = j.choices?.[0]?.message?.content;
  if (!txt) await fail("VLM 3425 无有效回复: " + JSON.stringify(j).slice(0, 200));
} catch (e) {
  await fail("VLM 3425 不可达: " + e.message);
}

const tasks = await fetch(`${OV}/api/v1/tasks?limit=200`).then((r) => r.json());
const q = (tasks.result || []).filter(
  (t) => t.task_type === "session_commit" && ["pending", "running"].includes(t.status)
);
if (q.length > MAX_QUEUE) {
  await fail(
    `session_commit 队列过深 (${q.length} > ${MAX_QUEUE})，请先 node scripts/ov-drain-commit-queue.mjs`
  );
}

console.log(JSON.stringify({ ok: true, commit_queue: q.length, max: MAX_QUEUE }));

